function heroGender(d){return ['male','female'].includes(d.gender)?d.gender:characterById(d.character).gender||'male'}
function matchingCharacter(id,gender){const role=careerRoles.find(([role])=>id===role+'-boy'||id===role+'-girl');if(role)return role[0]+(gender==='female'?'-girl':'-boy');if(id==='knight'||id==='knight-girl')return gender==='female'?'knight-girl':'knight';const c=characterById(id);return c.gender===gender?c.id:gender==='female'?'omani-girl':'omani-boy'}
function renderAdventureText(text,entry,gender,name,l){
 // A custom lead name may match a named friend; keep the friend distinct without changing their gender.
 for(const [key,c] of Object.entries(storyCast)){const companion=c[l];if(key!==entry.lead&&companion===name)text=text.split(companion).join(l==='ar'?(key==='somoud'?(gender==='female'?'صديقتها':'صديقته'):(gender==='female'?'صديقها':'صديقه')):'a friend');}
 return genderText(text,gender,name);
}
const authoredHeritageStory=heritageStory;
heritageStory=function(n,d,c){const entry=resolveTale(d);if(!entry?.templates){const result=authoredHeritageStory(n,d,c);if(result.historical&&heroGender(d)==='female'&&d.storyLanguage==='ar'){result.pages=result.pages.map((p,i)=>result.pageTypes?.[i]==='frame'?p.replace('صرت ملّاحًا','صرت ملّاحةً').replace('دفتر مستكشف صغير','دفتر مستكشفة صغيرة'):p);result.chapters=result.chapters.map(p=>p.replace('دفتر البطل','دفتر البطلة'));}return result;}const gender=heroGender(d),l=d.storyLanguage==='ar'?'ar':'en',cast=Object.values(storyCast).find(c=>c.ar===n||c.en===n),name=cast?cast[l]:(n?.trim()||storyCast[gender==='female'?'somoud':entry.lead==='somoud'?'isa':entry.lead][l]);const pages=entry.templates[l].map(p=>renderAdventureText(p,entry,gender,name,l));if(d.dedication)pages[0]=d.dedication+'\n\n'+pages[0];return{name,gender,title:genderText(entry.titleTemplates[l],gender,name),pages,chapters:pages.map((_,i)=>(l==='ar'?['بداية الحكاية','نتتبّع الدليل','فكرة تغيّر الطريق','نهاية تفتح بابًا']:['The story begins','Following a clue','An idea changes the way','An ending, a new beginning'])[Math.min(3,Math.floor(i*4/pages.length))]),historical:false,sources:[],value:l==='ar'?'فضول وتعاون وملاحظة… من داخل المغامرة':'Curiosity, teamwork and observation, within the adventure',activity:l==='ar'?'أيّ تفصيل غيّر الحكاية؟ ماذا كنت ستفعل مكان الشخصية الرئيسية؟':'Which detail changed the story? What would you have done?',location:d.landmark,storyId:entry.id,artPack:entry.pack,sceneSequence:entry.sequence};};
